	var e error
	record, e = db.BeginIdempotent(ctx, tx, db.IdempotencyScope{Principal: principalScope, Method: r.Method, Route: m.scope, KeyHash: kh[:], RequestHash: hash[:]}, c.Retention)
	if e != nil {
